<template>
  <div class="benefit-editor" data-benefit-editor>
    <PageHead :title="draft.id ? '自由组合／权益包配置' : '新建自由组合'" desc="选择设备与组成位置，核对规则后保存；适配对象与包含主机实物分别决定。"><el-button @click="back" :disabled="busy">{{ typeof route.query.returnTo === 'string' ? '返回原页面' : '返回权益包' }}</el-button><el-button v-if="draft.id && store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" :disabled="(dirty) || busy" @click="useCommon(draft.id)">复制组包</el-button></PageHead>
    <el-empty v-if="missing" description="权益包不存在，原配置未被重新创建。请返回列表查看。" />
    <template v-else>
      <el-alert v-if="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" title="当前角色可查看配置与已有清单；组包、保存和生成清单需维护权限。" type="info" :closable="false" class="editor-alert" />
      <el-alert v-if="stale" title="这份包配置已有新的修订。当前编辑已保留，请读取最新配置后再保存或生成清单。" type="warning" :closable="false" class="editor-alert"><el-button link @click="reload">读取最新配置</el-button></el-alert>
      <RuleExplanation v-if="guideFailure" :failure="guideFailure" :supported-recovery="['edit-input','repreview']" @recover="action => action === 'edit-input' ? (validation.issues[0] && locateIssue(validation.issues[0])) : makeDeliveryPreview()" /><el-alert v-else-if="error" :title="error" type="error" :closable="false" show-icon class="editor-alert" data-benefit-error />
      <section class="package-summary" aria-label="权益包摘要" data-benefit-summary>
        <div><strong>{{new Set(draft.goods.map(line=>line.skuId)).size}} 种商品 · {{draft.goods.length}} 个位置 · {{ validation.physicalCount }} 件 / 包</strong><span>{{ draft.services.length }} 项服务 · 按各自计量方式</span></div>
        <div><strong>{{ formatBenefitCents(draft.quote.amountCents) }}</strong><span>每包人工报价</span></div>
        <button class="summary-issues" @click="validation.issues[0] && locateIssue(validation.issues[0])" :disabled="!validation.issues.length">{{ validation.issues.length }} 处待处理</button>
        <span class="save-state" :class="{ 'is-dirty': unsaved }">{{saving?'正在保存':generating?'正在生成清单':error?'保存或处理未完成，输入保留':unsaved?'尚未保存':draft.id?'已保存':'新建草稿'}}</span>
      </section>
      <section class="panel package-header">
        <div class="name-row"><el-button @click="membersOpen = !membersOpen" :aria-expanded="membersOpen" data-toggle-package-members>{{ membersOpen ? '收起全部成员' : '展开全部成员' }}</el-button><el-input v-model="draft.name" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || saving || generating" placeholder="填写权益包名称" aria-label="权益包名称" data-benefit-name /><el-tag :type="draft.status === 'disabled' ? 'info' : !validation.canSaveAvailable && draft.id ? 'warning' : draft.status === 'available' ? 'success' : 'info'">{{ !validation.canSaveAvailable && draft.id && draft.status !== 'disabled' ? '需处理' : packageStatusLabels[draft.status] }}</el-tag><el-checkbox v-model="draft.favorite" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || saving || generating">常用包</el-checkbox></div>
        <p class="package-code" data-benefit-code>{{ draft.code || '编号待生成' }}<span v-if="draft.id"> · 修订 {{ draft.revision }}</span><span v-if="dirty"> · 未保存</span></p>
        <div class="device-row"><el-form-item label="适配设备" class="device-field"><el-select :model-value="deviceValue" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || saving || generating" filterable clearable placeholder="可不选择，作为普通组合包" aria-label="适配设备" data-benefit-device @change="requestDevice(String($event || ''))"><el-option label="不指定设备 · 普通组合包" value="" /><el-option-group label="具体销售设备 SKU"><el-option v-for="device in deviceSkus" :key="device.skuId" :label="`${device.code} · ${device.name} · ${device.spec}`" :value="`sku:${device.skuId}`" /></el-option-group><el-option-group label="已确认设备型号（不含手机商品）"><el-option v-for="model in models" :key="model.key" :label="`${model.label} · ${model.productTypeName} · ${{ manual: '独立型号', model: '已发布模型', template: '商品模板', legacy: '规划型号' }[model.source]}`" :value="`model:${model.key}`" /></el-option-group></el-select></el-form-item><div class="include-phone"><el-checkbox v-if="currentPhone && (!includedPhone || currentIsIncluded)" :model-value="currentIsIncluded" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || saving || generating" data-benefit-include-phone @update:model-value="includePhone($event === true)">包含这台手机</el-checkbox><span v-else class="muted">{{ draft.device?.kind === 'model' ? '仅选型号，不加入手机商品' : !draft.device ? '普通组合包，不作设备适配承诺' : '包内手机与当前适配设备分别保留' }}</span></div></div>
        <p class="device-summary" :class="{ 'issue-warn': !validation.deviceValid }" data-benefit-device-summary>{{ validation.deviceLabel }}</p>
        <div v-if="includedPhone && !currentIsIncluded" class="retained-phone"><p>包内仍保留原手机：<strong>{{ includedPhone.name }}</strong> · {{ includedPhone.code }}。切换适配对象没有替换它。</p><el-button v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" link type="danger" @click="includePhone(false)" :disabled="busy">移除原包内手机</el-button></div>
        <el-button v-if="draft.device?.kind === 'sku' && !validation.deviceValid" link type="primary" @click="router.push(`/skus/${encodeURIComponent(draft.device.skuId)}`)">前往设备详情处理型号</el-button>
      </section>
      <section class="panel" data-framework-binding><h2>选配框架</h2><p>{{ draft.framework ? `${draft.framework.name} · 修订 ${draft.framework.revision}（本包冻结规则）` : '自由组包／旧 SKU 白名单规则' }}</p><div v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')"><el-select v-model="frameworkId" clearable placeholder="选择框架或清空以解除" aria-label="使用选配框架"><el-option v-for="f in (store.data.benefitFrameworks||[]).filter(f=>f.status==='available')" :key="f.id" :value="f.id" :label="`${f.name} · 修订 ${f.revision}`"/></el-select><el-button @click="useFramework" :disabled="busy" data-apply-framework>预览并应用框架变更</el-button></div><details><summary>查看冻结组范围与规则</summary><p v-for="g in draft.framework?.groups||[]" :key="g.id">{{ g.name }} · {{ g.scope?.productTypeIds.map(id=>store.data.productTypes.find(t=>t.id===id)?.name||id).join('、') }} · {{ g.required?'必选':'可选' }} {{ g.minKinds }}～{{ g.maxKinds }} 种</p><p v-for="rule in draft.framework?.rules||[]" :key="rule.id" :data-frozen-group-rule="rule.id">{{selectionGroups.find(group=>group.id===rule.sourceGroupId)?.name||rule.sourceGroupId}} {{rule.kind==='requires'?'有选配时需要':rule.kind==='excludes'?'不能同时选择':'不支持规则'}} {{selectionGroups.find(group=>group.id===rule.targetGroupId)?.name||rule.targetGroupId}} · {{rule.note}}</p></details><p v-for="reason in frameworkEmptyReasons" :key="reason">{{ reason }}</p><el-button link :disabled="!store.can('product:compatibility:read')" @click="manageCompatibility()">查看／维护适用关系</el-button><el-button link @click="router.push('/benefit-packages')">管理选配框架</el-button></section>
      <BenefitReferenceSummary :totals="referenceTotals"/>
      <div v-show="membersOpen" class="narrow-pane-tabs" aria-label="组包区域"><el-radio-group v-model="narrowPane"><el-radio-button value="candidates">选商品</el-radio-button><el-radio-button value="contents">包内清单（{{ draft.goods.length + draft.services.length }}）</el-radio-button></el-radio-group></div>
      <div v-show="membersOpen" class="package-columns" :class="`pane-${narrowPane}`">
        <section class="panel candidate-panel">
          <div class="section-head"><h2>添加内容</h2><el-button v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" link type="primary" @click="editService()" data-benefit-add-service :disabled="busy">添加服务权益</el-button></div>
          <div v-if="selectionGroups.length" class="selection-group-nav" aria-label="当前选配组"><el-button :type="!activeGroupId?'primary':'default'" plain @click="activeGroupId=''">全部组</el-button><button v-for="group in selectionGroups.filter(group=>group.enabled)" :key="group.id" type="button" :data-selection-group="group.id" :class="{active:activeGroupId===group.id}" @click="activeGroupId=group.id"><strong>{{group.name}}</strong><small>{{group.id}} · {{group.required?'必选':'可选'}} {{group.minKinds}}～{{group.maxKinds}} 种</small><span>已选 {{groupCounts.get(group.id)?.kinds||0}} 种 · {{groupCounts.get(group.id)?.quantity||0}} 件</span></button></div><el-tabs v-model="candidateTab"><el-tab-pane label="适用销售配件" name="recommended" /><el-tab-pane label="其他商品" name="all" /><el-tab-pane label="常用包" name="common" /></el-tabs>
          <template v-if="candidateTab !== 'common'">
            <BenefitCandidatePanel v-model:keyword="keyword" v-model:product-type-id="productTypeId" :rows="candidateRows" :types="types" :empty-reasons="frameworkEmptyReasons" :has-device="!!draft.device" :can-edit="store.can(draft.id?'product:benefit:update':'product:benefit:create')" :busy="busy" :recommended="candidateTab==='recommended'" @add="addSku"/>
          </template>
          <template v-else><el-empty v-if="!commonPackages.length" description="保存的权益包可标记为常用，下次直接复制并调整。" /><article v-for="item in commonPackages" :key="item.id" class="common-card"><div><strong>{{ item.name || '未命名草稿' }}</strong><p class="muted">{{ item.code }} · {{ item.goods.length }} 种商品 / {{ item.services.length }} 项服务</p><p class="muted">参考报价：{{ formatBenefitCents(item.quote.amountCents) }}</p></div><el-button v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" @click="useCommon(item.id)" :disabled="busy">复制组包</el-button></article></template>
        </section>
        <section class="panel contents-panel" data-benefit-contents>
          <div class="section-head"><h2>包内清单</h2><span class="muted" data-benefit-counts>{{ validation.physicalCount }} 件实物 · {{ draft.services.length }} 项服务约定</span></div>
          <el-empty v-if="!draft.goods.length && !draft.services.length" description="从左侧加入具体商品，也可以单独添加服务权益。适配设备不会自动加入清单。" />
<section v-for="contentGroup in contentGroups" :key="contentGroup.key" :data-content-group="contentGroup.key" class="composition-group"><h3>{{contentGroup.name}} · {{new Set(contentGroup.rows.map(row=>row.line.skuId)).size}} 种 · {{contentGroup.rows.reduce((n,row)=>n+row.line.quantity,0)}} 件</h3>
          <article v-for="row in contentGroup.rows" :key="`${inputEpoch}:${row.line.id}`" class="goods-card" :data-benefit-goods="row.line.skuId" :data-benefit-position="row.line.id">
            <div class="goods-heading"><div><el-tag size="small" effect="plain">{{row.line.role==='host'||draft.compositionVersion!==2&&row.line.skuId===draft.includedPhoneSkuId?'包含主机':positionGroupName(row.line.id)}}</el-tag><strong>{{ row.summary.name }}</strong><p class="muted">{{ row.summary.code }} · {{ row.summary.typeName }} · {{ row.available ? '当前在售' : '停售或引用失效，需处理' }}</p><p class="muted">所属 SPU：{{ row.summary.familyName }}</p></div><el-button v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" link type="danger" :aria-label="`移除 ${row.summary.code}`" @click="removeSku(row.line.id)" :disabled="busy">移除</el-button></div>
            <p class="sku-spec">{{row.summary.spec}}</p><small class="position-id">选配位置 {{row.line.id}}</small><el-select v-if="draft.compositionVersion===2&&row.line.role!=='host'&&selectionGroups.length" :model-value="row.line.groupId||'$ungrouped'" :disabled="!store.can(draft.id?'product:benefit:update':'product:benefit:create')||busy" aria-label="位置所属组选配" @change="assignGroup(row.line.id,$event==='$ungrouped'?null:String($event))"><el-option value="$ungrouped" label="未分组／待指定"/><el-option v-for="group in selectionGroups.filter(group=>group.enabled)" :key="group.id" :value="group.id" :label="`${group.name} · ${group.id}`"/></el-select>
            <div class="quantity-row"><span>每包数量</span><BenefitIntegerInput :model-value="row.line.quantity" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || saving || generating" controls :label="`每包数量 ${row.summary.code}`" :data-benefit-quantity="row.line.skuId" @update:model-value="quantity(row.line.id, $event)" /><el-button v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" link type="primary" @click="chooseReplacement(row.line.id)" :data-benefit-replace="row.line.skuId" :disabled="busy">替换 SKU</el-button></div>
<p v-if="quantityErrors[row.line.id]" class="issue-error" role="alert">{{quantityErrors[row.line.id]}}</p>
            <BenefitReferenceInput :model-value="row.line.referencePrice" :quantity="row.line.quantity" :label="`参考单价 ${row.summary.code}`" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || busy" @validity-change="referenceValidity(row.line.id,$event)" @update:model-value="setReference(row.line.id,$event)"/><div class="compatibility-line"><el-tag size="small" :type="compatibilityTag(row.compatibility.basicStatus)">{{ compatibilityLabels[row.compatibility.basicStatus] }}</el-tag><span>快充：{{ compatibilityLabels[row.compatibility.fastChargeStatus] }}</span></div>
            <details class="compatibility-details"><summary>适配理由与使用条件</summary><p v-for="reason in row.compatibility.reasons" :key="reason">{{ reason }}</p><div v-for="capability in row.compatibility.capabilities" :key="capability.capability" class="capability-block"><strong>{{ capabilityLabels[capability.capability] }}：{{ compatibilityLabels[capability.status] }}</strong><p v-for="condition in capability.conditions" :key="condition.label">{{ {met:'已满足',unmet:'不满足',unknown:'需确认'}[condition.state] }} · {{ condition.label }}</p><p v-for="source in capability.sources" :key="source" class="muted">依据：{{ source }}</p>

            </div></details>
            <template v-for="capability in row.compatibility.capabilities" :key="`confirm:${capability.capability}`"><div v-if="capability.status === 'conditional' && (capability.capability === 'basic' || (capability.capability === 'fast-charge' && draft.requireFastCharge))" class="condition-confirmation" :data-benefit-condition="`${row.line.skuId}:${capability.capability}`"><p v-if="isConditionConfirmed(row.line.id, capability.capability === 'fast-charge' ? 'fast-charge' : 'basic')" class="tag-ok">已记录当前配置的交付前提确认；仍为有条件适用。</p><template v-else><h3>确认使用前提 · {{ capabilityLabels[capability.capability] }}</h3><p v-for="condition in capability.conditions" :key="condition.label">{{ condition.label }}</p><p>请记录如何满足或告知本次前提；此确认仅属于当前权益包。</p><el-input v-model="conditionNotes[`${row.line.id}:${capability.capability}`]" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || saving || generating" type="textarea" :rows="2" placeholder="填写本次如何满足或告知使用前提" :aria-label="`${row.summary.code} ${capabilityLabels[capability.capability]}确认说明`" /><el-button v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" :disabled="(!conditionNotes[`${row.line.id}:${capability.capability}`]?.trim()) || busy" @click="confirmCondition(row.line.id, capability.capability === 'fast-charge' ? 'fast-charge' : 'basic')" :data-benefit-confirm-condition="`${row.line.skuId}:${capability.capability}`">确认按此前提交付</el-button></template></div></template>
            <el-button v-if="draft.device && ['pending','incompatible'].includes(row.compatibility.basicStatus)" :disabled="!store.can('product:compatibility:read')" link type="primary" @click="manageCompatibility(row.line.skuId)">维护这件商品的适用关系</el-button>
          </article>
          </section>
          <article v-for="service in draft.services" :key="service.id" class="service-card" :data-benefit-service="service.id"><div class="section-head"><div><el-tag size="small" type="info" effect="plain">服务权益</el-tag><strong>{{ service.name }}</strong></div><div v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" class="row-actions"><el-button link type="primary" :disabled="busy" @click="editService(service)">编辑服务</el-button><el-button link type="danger" :disabled="busy" @click="removeService(service.id)">移除服务</el-button></div></div><p>{{ service.quantity }} {{ service.unit }} · {{ service.measurement === 'per-package' ? '每包计量，随包数相乘' : '本次交付计量，不随包数相乘' }}</p><BenefitReferenceInput :model-value="service.referencePrice" :quantity="service.quantity" :label="`服务参考单价 ${service.name}`" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || busy" @update:model-value="service.referencePrice = $event"/><p v-if="service.validity" class="muted">期限：{{ service.validity }}</p><p v-if="service.description" class="muted">{{ service.description }}</p></article>
          <el-button v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create')" @click="editService()" :disabled="busy">添加服务权益</el-button>
        </section>
      </div>
      <section class="panel quote-panel"><div class="section-head"><div><h2>整包报价</h2><p class="muted">人工填写每包价格，留空即未报价；0 元也可明确报价。</p></div><strong>{{ formatBenefitCents(draft.quote.amountCents) }}</strong></div><div class="quote-input"><el-input :model-value="quoteText" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || saving || generating" placeholder="未报价" inputmode="decimal" aria-label="每包报价（元）" data-benefit-quote @update:model-value="updateQuote"><template #prepend>人民币 ¥</template><template #append>元 / 包</template></el-input><el-button v-if="store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') && validation.quoteNeedsReview && !quoteError" @click="reviewQuote">已复核当前报价</el-button></div><p v-if="quoteError" role="alert" class="issue-error">{{ quoteError }}</p><p v-else-if="validation.quoteNeedsReview" class="issue-warn" data-benefit-quote-review>组成或数量变化后，原报价保留为待复核参考。正式交付需再次核对当前组成和报价。</p></section>
      <section class="panel advanced-panel"><el-collapse v-model="advancedOpen"><el-collapse-item name="rules" title="高级设置 · 选配规则与快充要求"><BenefitRuleEditor v-if="!draft.framework" :ref="instance => { ruleEditor = instance as InstanceType<typeof BenefitRuleEditor> | undefined }" :version2="draft.compositionVersion===2" :issues="validation.issues.filter(issue => issue.groupId)" v-model="draft.groups" v-model:enabled="draft.rulesEnabled" :candidates="allCandidates" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || saving || generating" /><el-divider /><el-checkbox v-model="draft.requireFastCharge" :disabled="!store.can(draft.id ? 'product:benefit:update' : 'product:benefit:create') || saving || generating" data-benefit-require-fast>整包须有已确认快充商品</el-checkbox><p class="muted fast-note">默认核对基本使用；开启后整包还须有已确认快充商品，普通壳膜仍按基本适用校验。快充按独立声明与真实条件判断，不按名称、接口或标称功率推断。</p></el-collapse-item></el-collapse></section>
